package br.com.equilibra.budget.application;
import br.com.equilibra.budget.infrastructure.CategoryBudgetRepository; import br.com.equilibra.category.infrastructure.CategoryRepository; import br.com.equilibra.shared.api.CurrentUser; import br.com.equilibra.transaction.infrastructure.FinancialTransactionRepository; import org.junit.jupiter.api.Test; import java.math.BigDecimal; import static org.assertj.core.api.Assertions.assertThat;
class BudgetSummaryServiceTest { @Test void formulasForBudgetConsumption(){BigDecimal planned=new BigDecimal("1000.00"), actual=new BigDecimal("750.00"); assertThat(planned.subtract(actual)).isEqualByComparingTo("250.00"); assertThat(actual.multiply(BigDecimal.valueOf(100)).divide(planned,2,java.math.RoundingMode.HALF_UP)).isEqualByComparingTo("75.00");} @Test void zeroBudgetHasNoPercentage(){BigDecimal planned=BigDecimal.ZERO; assertThat(planned.signum()).isZero();} }
